body.script:
const KEY='soroush_studio_data_v1';
let data=load();
let editingBot=null;
let currentPreviewMessages=[];

function initialData(){
 return {bots:[],menus:[],replies:[],users:[],logs:[],workspace:'فضای کاری من'};
}
function load(){
 try{return {...initialData(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}
 catch(e){return initialData()}
}
function save(){
 localStorage.setItem(KEY,JSON.stringify(data));
 refresh();
}
function fa(n){return Number(n||0).toLocaleString('fa-IR')}
function esc(s){
 return String(s??'').replace(/[&<>"']/g,c=>({'&':'&','<':'<','>':'>','"':'"',"'":'''}[c]));
}
function toast(msg){
 let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');
 setTimeout(()=>t.classList.remove('show'),2500);
}
function log(action,detail){
 data.logs.unshift({action,detail,time:new Date().toLocaleString('fa-IR')});
 data.logs=data.logs.slice(0,100);
}
const titles={
 dashboard:['داشبورد مدیریت','مرکز فرماندهی ربات‌های شما'],
 bots:['ربات‌های من','مدیریت پروژه‌های رباتی'],
 builder:['طراحی منو','ساخت دکمه‌ها و مسیرهای تعاملی'],
 replies:['پاسخ خودکار','تعریف قوانین پاسخ‌گویی'],
 users:['مدیریت کاربران','دفترچه کاربران فضای کاری'],
 analytics:['گزارش‌ها','آمار اطلاعات ذخیره‌شده'],
 preview:['پیش‌نمایش','آزمایش رفتار ربات در محیط نمایشی'],
 settings:['تنظیمات','مدیریت فضای کاری و پشتیبان']
};
function go(page){
 document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
 document.getElementById(page).classList.add('active');
 document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 document.getElementById('pageTitle').textContent=titles[page][0];
 document.getElementById('pageSub').textContent=titles[page][1];
 if(page==='preview')renderPreview();
 if(page==='builder')renderMenus();
 if(page==='replies')renderReplies();
}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));

function openBotModal(id=null){
 editingBot=id;
 let bot=data.bots.find(x=>x.id===id);
 document.getElementById('botModalTitle').textContent=bot?'ویرایش ربات':'ساخت ربات جدید';
 document.getElementById('botName').value=bot?.name||'';
 document.getElementById('botDesc').value=bot?.desc||'';
 document.getElementById('botIcon').value=bot?.icon||'🤖';
 document.getElementById('botModal').classList.add('show');
}
function closeModal(){document.getElementById('botModal').classList.remove('show')}
function saveBot(){
 let name=document.getElementById('botName').value.trim();
 if(!name){toast('نام ربات را وارد کنید');return}
 let desc=document.getElementById('botDesc').value.trim();
 let icon=document.getElementById('botIcon').value;
 if(editingBot){
  let b=data.bots.find(x=>x.id===editingBot);
  if(b){b.name=name;b.desc=desc;b.icon=icon}
  log('ویرایش ربات',name);
 }else{
  let id=crypto.randomUUID?crypto.randomUUID():String(Date.now());
  data.bots.push({id,name,desc,icon,active:true,created:new Date().toLocaleDateString('fa-IR')});
  log('ساخت ربات',name);
 }
 save();closeModal();toast('ربات ذخیره شد');
}
function toggleBot(id){
 let b=data.bots.find(x=>x.id===id);if(!b)return;
 b.active=!b.active;log('تغییر وضعیت',b.name);
 save();toast('وضعیت ربات تغییر کرد');
}
function deleteBot(id){
 let b=data.bots.find(x=>x.id===id);if(!b)return;
 if(!confirm('ربات و منوها و پاسخ‌های مرتبط با آن حذف شوند؟'))return;
 data.bots=data.bots.filter(x=>x.id!==id);
 data.menus=data.menus.filter(x=>x.botId!==id);
 data.replies=data.replies.filter(x=>x.botId!==id);
 log('حذف ربات',b.name);save();toast('ربات حذف شد');
}
function botCard(b){
 return `

${esc(b.icon)}

${esc(b.name)}
${esc(b.desc||'بدون توضیحات')}

${b.active?'فعال':'غیرفعال'}${esc(b.created||'')}

ویرایش
 ${b.active?'توقف':'فعال‌سازی'}
 حذف
 `;
}
function renderBots(){
 let q=(document.getElementById('botSearch')?.value||'').toLowerCase();
 let arr=data.bots.filter(b=>b.name.toLowerCase().includes(q));
 document.getElementById('allBots').innerHTML=arr.length?arr.map(botCard).join(''):'
هنوز رباتی ساخته نشده است.';
}
function addMenu(){
 let botId=document.getElementById('menuBot').value;
 let label=document.getElementById('menuLabel').value.trim();
 let response=document.getElementById('menuResponse').value.trim();
 if(!botId){toast('ابتدا یک ربات بسازید');return}
 if(!label||!response){toast('عنوان و پاسخ را کامل کنید');return}
 data.menus.push({id:String(Date.now()),botId,label,response});
 log('افزودن دکمه',label);save();
 document.getElementById('menuLabel').value='';
 document.getElementById('menuResponse').value='';
 toast('دکمه اضافه شد');
}
function renderMenus(){
 fillBotSelect('menuBot');
 let id=document.getElementById('menuBot').value;
 let arr=data.menus.filter(m=>m.botId===id);
 document.getElementById('menuList').innerHTML=arr.length?arr.map(m=>`

${esc(m.label)}${esc(m.response)}
 حذف`).join(''):'
هنوز دکمه‌ای ساخته نشده است.';
}
function deleteMenu(id){
 data.menus=data.menus.filter(m=>m.id!==id);log('حذف دکمه','منوی ربات');save();toast('دکمه حذف شد');
}
function addReply(){
 let botId=document.getElementById('replyBot').value;
 let key=document.getElementById('replyKey').value.trim();
 let text=document.getElementById('replyText').value.trim();
 let match=document.getElementById('replyMatch').value;
 if(!botId){toast('ابتدا ربات بسازید');return}
 if(!key||!text){toast('کلیدواژه و پاسخ را وارد کنید');return}
 data.replies.push({id:String(Date.now()),botId,key,text,match});
 log('افزودن پاسخ خودکار',key);save();
 document.getElementById('replyKey').value='';
 document.getElementById('replyText').value='';
 toast('قانون پاسخ ثبت شد');
}
function renderReplies(){
 fillBotSelect('replyBot');
 let rows=data.replies.map(r=>{
 let b=data.bots.find(x=>x.id===r.botId);
 return `
${esc(b?.name||'حذف‌شده')}${esc(r.key)}${r.match==='exact'?'برابر':'شامل'}${esc(r.text.slice(0,55))}حذف`;
 }).join('');
 document.getElementById('replyTable').innerHTML=rows||'
قانونی ثبت نشده است.';
}
function deleteReply(id){
 data.replies=data.replies.filter(r=>r.id!==id);log('حذف پاسخ','قانون پاسخ خودکار');save();toast('پاسخ حذف شد');
}
function addUser(){
 let name=prompt('نام نمایشی کاربر را وارد کنید:');if(!name?.trim())return;
 let id='local_'+Date.now();
 data.users.push({id,name:name.trim(),date:new Date().toLocaleDateString('fa-IR'),status:'آزمایشی'});
 log('افزودن کاربر آزمایشی',name);save();toast('کاربر محلی اضافه شد');
}
function renderUsers(){
 let q=(document.getElementById('userSearch')?.value||'').toLowerCase();
 let arr=data.users.filter(u=>u.name.toLowerCase().includes(q)||u.id.toLowerCase().includes(q));
 document.getElementById('userTable').innerHTML=arr.length?arr.map(u=>`
${esc(u.name)}${esc(u.id)}${esc(u.status)}${esc(u.date)}حذف`).join(''):'
کاربری وجود ندارد.';
}
function deleteUser(id){
 data.users=data.users.filter(u=>u.id!==id);log('حذف کاربر','کاربر محلی');save();
}
function fillBotSelect(id){
 let el=document.getElementById(id);if(!el)return;
 let old=el.value;
 el.innerHTML=data.bots.map(b=>`${esc(b.name)}`).join('');
 if(data.bots.some(b=>b.id===old))el.value=old;
}
function renderPreview(){
 fillBotSelect('previewBot');
 let id=document.getElementById('previewBot').value;
 let b=data.bots.find(x=>x.id===id);
 document.getElementById('previewName').textContent=b?.name||'ربات شما';
 document.getElementById('previewButtons').innerHTML=data.menus.filter(m=>m.botId===id).map(m=>`${esc(m.label)}`).join('');
 document.getElementById('previewMessages').innerHTML=currentPreviewMessages.map(m=>`
${esc(m.text)}`).join('');
}
function previewMenu(id){
 let m=data.menus.find(x=>x.id===id);if(!m)return;
 currentPreviewMessages.push({text:m.label,user:true},{text:m.response,user:false});
 renderPreview();
}
function sendPreview(){
 let value=document.getElementById('testMessage').value.trim();if(!value)return;
 let id=document.getElementById('previewBot').value;
 currentPreviewMessages.push({text:value,user:true});
 let r=data.replies.find(x=>x.botId===id&&(x.match==='exact'?value===x.key:value.includes(x.key)));
 currentPreviewMessages.push({text:r?.text||'برای این پیام پاسخ خودکاری تعریف نشده است.',user:false});
 document.getElementById('testMessage').value='';renderPreview();
}
function refresh(){
 let active=data.bots.filter(b=>b.active).length;
 document.getElementById('statBots').textContent=fa(data.bots.length);
 document.getElementById('statActive').textContent=fa(active);
 document.getElementById('statReplies').textContent=fa(data.replies.length);
 document.getElementById('statUsers').textContent=fa(data.users.length);
 document.getElementById('anaMenus').textContent=fa(data.menus.length);
 document.getElementById('anaReplies').textContent=fa(data.replies.length);
 document.getElementById('anaLogs').textContent=fa(data.logs.length);
 document.getElementById('anaUsers').textContent=fa(data.users.length);
 document.getElementById('recentBots').innerHTML=data.bots.slice(-3).reverse().map(botCard).join('')||'
برای شروع اولین ربات خود را بسازید.';
 document.getElementById('recentLogs').innerHTML=data.logs.slice(0,5).map(l=>`
${esc(l.action)} — ${esc(l.detail)}${esc(l.time)}`).join('')||'
هنوز فعالیتی ثبت نشده است.';
 document.getElementById('analyticsText').textContent=`${fa(data.bots.length)} ربات، ${fa(data.menus.length)} دکمه، ${fa(data.replies.length)} قانون پاسخ و ${fa(data.users.length)} کاربر محلی در فضای کاری ثبت شده است.`;
 renderBots();renderMenus();renderReplies();renderUsers();
}
function exportData(){
 let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
 let a=document.createElement('a');a.href=URL.createObjectURL(blob);
 a.download='soroush-studio-backup.json';a.click();URL.revokeObjectURL(a.href);
 toast('فایل پشتیبان آماده شد');
}
function importData(event){
 let file=event.target.files[0];if(!file)return;
 let reader=new FileReader();
 reader.onload=()=>{
  try{
   let x=JSON.parse(reader.result);
   if(!x||!Array.isArray(x.bots)||!Array.isArray(x.menus)||!Array.isArray(x.replies))throw Error();
   data={...initialData(),...x};save();toast('اطلاعات بازیابی شد');
  }catch(e){toast('فایل پشتیبان معتبر نیست')}
 };
 reader.readAsText(file);
}
function saveWorkspace(){
 data.workspace=document.getElementById('workspaceName').value.trim()||'فضای کاری من';
 save();toast('تنظیمات ذخیره شد');
}
function resetData(){
 if(!confirm('تمام اطلاعات محلی این برنامه پاک شود؟'))return;
 data=initialData();save();toast('اطلاعات پاک شد');
}
refresh();
document.getElementById('workspaceName').value=data.workspace||'فضای کاری من';
